service.method:

UPDATE SSIGN
   SET LINK = ${LINK}
WHERE HOUSE_CODE    = ${session.HOUSE_CODE}
  AND CONT_NO       = ${CONT_NO}
  AND CONT_GL_SEQ   = ${CONT_GL_SEQ}
  AND SIGNER_NO     = ${SIGNER_NO}


DELETE
  FROM ULNUS 
 WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
   AND CODE              = ${CODE}
   AND PRIVATE_CODE      = ${PRIVATE_CODE}
